using System.Globalization;
using System.Reflection;
using System.Text.RegularExpressions;
using System.Text.Json.Serialization;
using AReport.Designer.Mvvm;
using AReport.Model;

namespace AReport.Designer;

public enum RowKind { Text, Number, Color, Toggle, Choice, Collection }

/// <summary>One editable line of the properties panel, generated by reflection from a model object.</summary>
public sealed class PropertyRow : ObservableObject
{
    private static readonly NullabilityInfoContext Nullability = new();

    private readonly PropertyInfo _property;
    private readonly object _target;
    private readonly Action<Action> _mutate;
    private readonly bool _nullable;
    private string? _pending;
    private string? _error;

    private PropertyRow(PropertyInfo property, object target, Action<Action> mutate, Action? editCollection)
    {
        _property = property;
        _target = target;
        _mutate = mutate;
        EditCollection = editCollection;
        _nullable = property.PropertyType == typeof(string) && Nullability.Create(property).WriteState == NullabilityState.Nullable;

        Label = MakeLabel(property.Name);
        var type = property.PropertyType;
        Kind = type == typeof(bool) ? RowKind.Toggle
            : type.IsEnum ? RowKind.Choice
            : type == typeof(double) ? RowKind.Number
            : type == typeof(string) && property.Name.EndsWith("Color", StringComparison.Ordinal) ? RowKind.Color
            : type == typeof(string) ? RowKind.Text
            : RowKind.Collection;
        IsReadOnly = !property.CanWrite || property.Name == nameof(ReportElement.Id);
        IsMultiline = Kind == RowKind.Text && property.Name == nameof(TextElement.Text);
        Choices = type.IsEnum ? Enum.GetNames(type) : [];
    }

    public string Name => _property.Name;
    public string Label { get; }
    public RowKind Kind { get; }
    public bool IsReadOnly { get; }
    public bool IsMultiline { get; }
    public IReadOnlyList<string> Choices { get; }
    public Action? EditCollection { get; }

    public bool IsTextual => Kind is RowKind.Text or RowKind.Number or RowKind.Color;
    public bool IsToggle => Kind == RowKind.Toggle;
    public bool IsChoice => Kind == RowKind.Choice;
    public bool IsCollection => Kind == RowKind.Collection;
    public bool HasColor => Kind == RowKind.Color;
    public bool CanEdit => !IsReadOnly;
    public bool ShowLabel => Kind != RowKind.Toggle;

    /// <summary>A message when the typed text was rejected; empty otherwise. Always shown as words, never colour alone.</summary>
    public string Error => _error ?? "";
    public bool HasError => _error is not null;

    public string Text
    {
        get => _pending ?? FormatCurrent();
        set => Commit(value ?? "");
    }

    public bool IsChecked
    {
        get => _property.GetValue(_target) is true;
        set => _mutate(() => _property.SetValue(_target, value));
    }

    public string? SelectedChoice
    {
        get => _property.GetValue(_target)?.ToString();
        set
        {
            if (value is null) return;
            _mutate(() => _property.SetValue(_target, Enum.Parse(_property.PropertyType, value)));
        }
    }

    /// <summary>For colour rows: the hex text if it is a valid colour, so the view can paint a swatch.</summary>
    public string? SwatchHex => HasColor && RgbColor.TryParse(Text, out _) ? Text : null;

    /// <summary>Re-reads the value from the model (after a drag, undo, …).</summary>
    public void Refresh()
    {
        _pending = null;
        SetError(null);
        OnPropertyChanged(nameof(Text));
        OnPropertyChanged(nameof(IsChecked));
        OnPropertyChanged(nameof(SelectedChoice));
        OnPropertyChanged(nameof(SwatchHex));
    }

    private void Commit(string text)
    {
        _pending = text;
        switch (Kind)
        {
            case RowKind.Number:
                if (!TryParseNumber(text, out var number))
                {
                    Reject("Enter a number.");
                    return;
                }
                Apply(number);
                break;

            case RowKind.Color:
                if (text.Length == 0 && _nullable)
                {
                    Apply(null);
                    break;
                }
                if (!RgbColor.TryParse(text, out _))
                {
                    Reject("Use a colour like #1F3A5F.");
                    return;
                }
                Apply(text.Trim().ToUpperInvariant());
                break;

            default:
                Apply(text.Length == 0 && _nullable ? null : text);
                break;
        }
    }

    private void Apply(object? value)
    {
        _pending = null;
        SetError(null);
        if (!Equals(_property.GetValue(_target), value))
            _mutate(() => _property.SetValue(_target, value));
        OnPropertyChanged(nameof(Text));
        OnPropertyChanged(nameof(SwatchHex));
    }

    private void Reject(string message)
    {
        SetError(message);
        OnPropertyChanged(nameof(Text));
    }

    private void SetError(string? message)
    {
        if (_error == message) return;
        _error = message;
        OnPropertyChanged(nameof(Error));
        OnPropertyChanged(nameof(HasError));
    }

    private string FormatCurrent()
    {
        var value = _property.GetValue(_target);
        return value switch
        {
            null => "",
            double d => d.ToString("0.###", CultureInfo.CurrentCulture),
            _ => value.ToString() ?? "",
        };
    }

    private static bool TryParseNumber(string text, out double value) =>
        double.TryParse(text, NumberStyles.Float, CultureInfo.CurrentCulture, out value)
        || double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out value);

    internal static string MakeLabel(string name)
    {
        var words = Regex.Replace(name, "(?<=[a-z0-9])(?=[A-Z])", " ").Split(' ');
        return string.Join(' ', words.Select((w, i) => i == 0 ? w : w.ToLowerInvariant()));
    }

    /// <summary>Rows for every editable property of <paramref name="target"/>. Base-element properties first, then type-specific ones.</summary>
    public static List<PropertyRow> Build(object target, Action<Action> mutate, Action? editColumns = null, IReadOnlySet<string>? only = null)
    {
        var properties = target.GetType()
            .GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Where(p => p.GetIndexParameters().Length == 0 && p.GetCustomAttribute<JsonIgnoreAttribute>() is null)
            .Where(p => only is null || only.Contains(p.Name))
            .Where(p => p.PropertyType != typeof(List<TableColumn>) || editColumns is not null)
            .OrderBy(p => p.Name == nameof(ReportElement.Id) ? 2 : p.DeclaringType == typeof(ReportElement) ? 0 : 1)
            .ThenBy(p => p.MetadataToken)
            .ToList();

        return properties.Select(p => new PropertyRow(p, target, mutate, p.PropertyType == typeof(List<TableColumn>) ? editColumns : null)).ToList();
    }
}
